type RunnerKeyStatus uint8

const (
	RunnerKeyStatus_Ok              RunnerKeyStatus = 0
	RunnerKeyStatus_AlreadyEnrolled RunnerKeyStatus = 1
	RunnerKeyStatus_NotFound        RunnerKeyStatus = 2
	RunnerKeyStatus_AmbiguousPrefix RunnerKeyStatus = 3
	RunnerKeyStatus_InUse           RunnerKeyStatus = 4
	RunnerKeyStatus_InvalidKey      RunnerKeyStatus = 5
)

func (e RunnerKeyStatus) String() string {
	switch e {
	case RunnerKeyStatus_Ok:
		return "ok"
	case RunnerKeyStatus_AlreadyEnrolled:
		return "already_enrolled"
	case RunnerKeyStatus_NotFound:
		return "not_found"
	case RunnerKeyStatus_AmbiguousPrefix:
		return "ambiguous_prefix"
	case RunnerKeyStatus_InUse:
		return "in_use"
	case RunnerKeyStatus_InvalidKey:
		return "invalid_key"
	default:
		return fmt.Sprintf("RunnerKeyStatus(%d)", e)
	}
}

